const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const eastLoc = ee.Geometry.Point([-137.527803, 48.504441]);
  const westLoc = ee.Geometry.Point([-169.318365, 46.750838]);

  const baseline_start = '2003-01-01';
  const baseline_end = '2012-12-31';
  const target_start = '2016-01-01';
  const target_end = '2016-01-31';

  // 2. Data Acquisition
  const sstCollection = ee.ImageCollection('NOAA/CDR/SSTWHOI/V2')
    .select('sea_surface_temperature');

  // Get baseline average (2003-2012)
  const baselineCol = sstCollection
    .filterDate(baseline_start, baseline_end)
    .filter(ee.Filter.calendarRange(1, 1, 'month')); // January only

  const baselineSize = baselineCol.size().getInfo();
  console.log(`Baseline images (Jan 2003-2012): ${baselineSize}`);

  if (baselineSize === 0) {
    console.log('No baseline data found.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get January 2016 data
  const targetCol = sstCollection
    .filterDate(target_start, target_end);

  const targetSize = targetCol.size().getInfo();
  console.log(`Target images (Jan 2016): ${targetSize}`);

  if (targetSize === 0) {
    console.log('No data for January 2016.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Calculate baseline means
  const baselineMean = baselineCol.mean();
  const targetMean = targetCol.mean();

  // 4. Calculate anomalies
  const anomaly = targetMean.subtract(baselineMean);

  // 5. Extract values at both locations
  const scale = 5000;

  // Eastern location
  const eastAnomaly = anomaly.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: eastLoc,
    scale: scale,
    maxPixels: 1e9
  }).get('sea_surface_temperature');

  const eastCount = anomaly.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: eastLoc,
    scale: scale,
    maxPixels: 1e9
  }).get('sea_surface_temperature');

  // Western location
  const westAnomaly = anomaly.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: westLoc,
    scale: scale,
    maxPixels: 1e9
  }).get('sea_surface_temperature');

  const westCount = anomaly.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: westLoc,
    scale: scale,
    maxPixels: 1e9
  }).get('sea_surface_temperature');

  // Get values
  const eastVal = eastAnomaly.getInfo();
  const westVal = westAnomaly.getInfo();
  const eastPixels = eastCount.getInfo();
  const westPixels = westCount.getInfo();

  console.log(`East location (${eastLoc.coordinates().getInfo()}): Anomaly=${eastVal}, Pixels=${eastPixels}`);
  console.log(`West location (${westLoc.coordinates().getInfo()}): Anomaly=${westVal}, Pixels=${westPixels}`);

  // 6. Validation & Final Answer
  if (eastPixels === 0 || westPixels === 0) {
    console.log('No valid pixels at one or both locations.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (eastVal === null || westVal === null || isNaN(eastVal) || isNaN(westVal)) {
    console.log('Calculation failed - null or NaN result.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Check reasonable range for SST anomaly (-10 to +10°C)
  if (Math.abs(eastVal) > 10 || Math.abs(westVal) > 10) {
    console.log('Anomaly values outside reasonable range.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`\nComparison: East anomaly (${eastVal.toFixed(3)}°C) vs West anomaly (${westVal.toFixed(3)}°C)`);

  if (eastVal > westVal) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
